import React from 'react';
import { useLanguage } from '../../context/LanguageContext';

export const LanguageToggle = () => {
  const { language, setLanguage } = useLanguage();
  const label = {
    fr: 'Langue',
    en: 'Language'
  }[language];

  return (
    <>
      <label className="sr-only" htmlFor="language-select">{label}</label>
      <select
        id="language-select"
        value={language}
        onChange={(event) => setLanguage(event.target.value)}
        aria-label={label}
        className="h-9 rounded-md border border-[var(--line)] bg-[var(--surface)] px-2 text-xs font-semibold text-[var(--ink)]"
      >
        <option value="fr">FR</option>
        <option value="en">EN</option>
      </select>
    </>
  );
};
