import React from 'react';
import { Moon, Sun } from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { useLanguage } from '../../context/LanguageContext';
import { motion } from 'framer-motion';

export const ThemeToggle = () => {
  const { theme, toggleTheme } = useTheme();
  const { language } = useLanguage();
  const labels = {
    fr: ['Activer le thème sombre', 'Activer le thème clair'],
    en: ['Switch to dark theme', 'Switch to light theme'],
    ar: ['تفعيل المظهر الداكن', 'تفعيل المظهر الفاتح'],
    es: ['Activar tema oscuro', 'Activar tema claro']
  }[language];
  const label = theme === 'light' ? labels[0] : labels[1];

  return (
    <motion.button
      type="button"
      onClick={toggleTheme}
      aria-label={label}
      title={label}
      className="rounded-md p-2 text-[var(--muted)] transition-colors hover:bg-[var(--accent-soft)] hover:text-[var(--accent)]"
    >
      {theme === 'light' ? <Moon size={20} /> : <Sun size={20} />}
    </motion.button>
  );
};
