import React from 'react';
import { portfolioData } from '../../data/portfolioData';
import { useLanguage } from '../../context/LanguageContext';
import { ArrowUp, Github, Linkedin, Mail } from 'lucide-react';

export const Footer = () => {
  const { language } = useLanguage();
  const social = portfolioData.social.filter((item) => item.icon !== 'Instagram');
  const icons = { Github, Linkedin, Mail };
  const backLabel = { fr: 'Retour en haut', en: 'Back to top', ar: 'العودة للأعلى', es: 'Volver arriba' }[language];

  return (
    <footer className="mt-12 border-t border-[var(--line)]">
      <div className="page-container flex flex-col items-center justify-between gap-5 py-8 text-center sm:flex-row sm:text-start">
        <div>
          <p className="text-sm font-semibold">Mohammed Yousfi</p>
          <p className="mt-1 text-xs text-[var(--muted)]">Software Engineering Student · Web Developer</p>
          <p className="mt-1 text-xs text-[var(--muted)]">© 2026 Mohammed Yousfi. All rights reserved.</p>
        </div>

        <div className="flex items-center gap-2">
          {social.map((item) => {
            const Icon = icons[item.icon];
            return (
              <a
                key={item.name}
                href={item.url}
                target={item.url.startsWith('mailto:') ? undefined : '_blank'}
                rel={item.url.startsWith('mailto:') ? undefined : 'noopener noreferrer'}
                aria-label={item.name}
                className="rounded-md p-2 text-[var(--muted)] transition-colors hover:bg-[var(--accent-soft)] hover:text-[var(--accent)]"
              >
                <Icon size={20} />
              </a>
            );
          })}
          <a href="#home" aria-label={backLabel} className="ml-2 rounded-md border border-[var(--line)] p-2 text-[var(--muted)] hover:text-[var(--accent-bright)]">
            <ArrowUp size={18} />
          </a>
        </div>
      </div>
    </footer>
  );
};
