const redirectPath = new URLSearchParams(window.location.search).get('__gh_pages_path');

if (redirectPath && redirectPath.startsWith('/') && !redirectPath.startsWith('//')) {
  const redirectUrl = new URL(redirectPath, window.location.origin);
  const route = redirectUrl.pathname.replace(/\/+$/, '') || '/';
  const supportedRoutes = ['/about', '/skills', '/projects', '/experience', '/contact', '/dashboard'];

  if (
    redirectUrl.origin === window.location.origin &&
    (supportedRoutes.includes(route) || route.startsWith('/dashboard/'))
  ) {
    const basePath = (process.env.PUBLIC_URL || '').replace(/\/$/, '');
    window.history.replaceState(
      null,
      '',
      `${basePath}${route}${redirectUrl.search}${redirectUrl.hash}`
    );
  }
}
