import React, { useEffect, useMemo, useState } from 'react';
import { useLanguage } from '../../context/LanguageContext';
import { ThemeToggle } from './ThemeToggle';
import { LanguageToggle } from './LanguageToggle';
import { AnimatePresence, motion } from 'framer-motion';
import { Menu, X } from 'lucide-react';

export const Navbar = () => {
  const { language } = useLanguage();
  const [isOpen, setIsOpen] = useState(false);
  const [activeSection, setActiveSection] = useState('home');
  const copy = {
    fr: { home: 'Accueil', about: 'À propos', skills: 'Compétences', projects: 'Projets', education: 'Formation', contact: 'Contact', menu: 'Ouvrir le menu', close: 'Fermer le menu' },
    en: { home: 'Home', about: 'About', skills: 'Skills', projects: 'Projects', education: 'Education', contact: 'Contact', menu: 'Open menu', close: 'Close menu' }
  }[language];

  const links = useMemo(() => [
    { name: copy.home, id: 'home' },
    { name: copy.about, id: 'about' },
    { name: copy.skills, id: 'skills' },
    { name: copy.projects, id: 'projects' },
    { name: copy.education, id: 'education' },
    { name: copy.contact, id: 'contact' }
  ], [copy]);

  useEffect(() => {
    const sections = links.map((link) => document.getElementById(link.id)).filter(Boolean);
    if (!sections.length || !('IntersectionObserver' in window)) return undefined;
    const observer = new IntersectionObserver((entries) => {
      const visible = entries.filter((entry) => entry.isIntersecting).sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
      if (visible) setActiveSection(visible.target.id);
    }, { rootMargin: '-25% 0px -60%', threshold: [0.05, 0.25, 0.5] });
    sections.forEach((section) => observer.observe(section));
    return () => observer.disconnect();
  }, [links]);

  useEffect(() => {
    if (!isOpen) return undefined;
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') setIsOpen(false);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen]);

  const sectionHref = (id) => `#${id}`;

  return (
    <header className="sticky top-0 z-50 border-b border-[var(--line)] bg-[var(--page)]/90 backdrop-blur-xl">
      <nav className="page-container" aria-label="Main navigation">
        <div className="flex min-h-[76px] items-center justify-between gap-5">
          <a href={sectionHref('home')} className="flex shrink-0 items-center gap-3" aria-label="Mohammed Yousfi — home">
            <span className="flex h-9 w-9 items-center justify-center rounded-lg border border-[var(--accent)]/40 bg-[linear-gradient(135deg,var(--accent-soft),rgba(71,123,255,.12))] text-sm font-black tracking-tight text-white shadow-[0_8px_24px_rgba(118,82,255,.18)]">MY</span>
            <span className="hidden text-sm font-semibold sm:inline">Mohammed Yousfi</span>
          </a>

          <div className="hidden items-center gap-1 lg:flex">
            {links.map((link) => (
              <a
                key={link.id}
                href={sectionHref(link.id)}
                aria-current={activeSection === link.id ? 'location' : undefined}
                className={`rounded-md px-3 py-2 text-sm transition-colors ${
                  activeSection === link.id ? 'text-[var(--accent-bright)]' : 'text-[var(--muted)] hover:text-[var(--ink)]'
                }`}
              >
                {link.name}
              </a>
            ))}
          </div>

          <div className="flex items-center gap-1">
            <ThemeToggle />
            <LanguageToggle />
            <button
              type="button"
              className="rounded-md p-2 text-[var(--ink)] lg:hidden"
              onClick={() => setIsOpen((open) => !open)}
              aria-label={isOpen ? copy.close : copy.menu}
              aria-expanded={isOpen}
              aria-controls="mobile-navigation"
            >
              {isOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>

        <AnimatePresence>
          {isOpen && (
            <motion.div
              id="mobile-navigation"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="overflow-hidden lg:hidden"
            >
              <div className="grid border-t border-[var(--line)] py-3">
                {links.map((link) => (
                  <a
                    key={link.id}
                    href={sectionHref(link.id)}
                    onClick={() => setIsOpen(false)}
                    aria-current={activeSection === link.id ? 'location' : undefined}
                    className={`rounded-md px-3 py-3 text-sm ${activeSection === link.id ? 'text-[var(--accent-bright)]' : 'text-[var(--muted)]'}`}
                  >
                    {link.name}
                  </a>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </nav>
    </header>
  );
};
