const retryKey = 'portfolio-chunk-load-retry';
const retryParameter = '_chunk_retry';

const isChunkLoadError = (error) => (
  error?.name === 'ChunkLoadError' ||
  /Loading chunk \d+ failed/i.test(error?.message || '')
);

const reloadWithFreshHtml = (error) => {
  if (!isChunkLoadError(error) || window.sessionStorage.getItem(retryKey) === '1') return;

  window.sessionStorage.setItem(retryKey, '1');
  const url = new URL(window.location.href);
  url.searchParams.set(retryParameter, Date.now().toString());
  window.location.replace(url.toString());
};

window.addEventListener('unhandledrejection', (event) => {
  reloadWithFreshHtml(event.reason);
});

window.addEventListener('error', (event) => {
  reloadWithFreshHtml(event.error || { message: event.message });
});

if (new URL(window.location.href).searchParams.has(retryParameter)) {
  window.setTimeout(() => {
    window.sessionStorage.removeItem(retryKey);
  }, 30000);
}
